/* EARTHUS V2 — imagery-only geodetic polar hole fill.
 * Fills only the extreme-pole geometry gap left by the terrain service.
 * Source pixels are NASA GIBS EPSG:4326 Blue Marble. No elevation is invented.
 */
const WMS='https://gibs.earthdata.nasa.gov/wms/epsg4326/best/wms.cgi';
const EDGE_LAT=82.5;
const SEGMENTS=256;
const RINGS=28;
const HEIGHT_M=120;
const LAYERS=Object.freeze(['BlueMarble_NextGeneration','BlueMarble_ShadedRelief_Bathymetry','BlueMarble_ShadedRelief']);
function urlFor(north,layer){const south=north?EDGE_LAT:-90,northLat=north?90:-EDGE_LAT,u=new URL(WMS);u.search=new URLSearchParams({service:'WMS',version:'1.1.1',request:'GetMap',styles:'',layers:layer,srs:'EPSG:4326',bbox:`-180,${south},180,${northLat}`,width:'2048',height:'512',format:'image/jpeg',transparent:'false'}).toString();return u.href}
async function loadImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.decoding='async';image.onload=()=>image.naturalWidth>=1024&&image.naturalHeight>=256?resolve(image):reject(new Error('POLAR_GEOGRAPHIC_IMAGE_DIMENSION_GATE'));image.onerror=()=>reject(new Error('POLAR_GEOGRAPHIC_IMAGE_DECODE_FAILED'));image.src=url})}
function imageSignal(image){const cv=document.createElement('canvas');cv.width=256;cv.height=64;const cx=cv.getContext('2d',{willReadFrequently:true});if(!cx)throw new Error('POLAR_GEOGRAPHIC_CANVAS_CONTEXT');cx.drawImage(image,0,0,cv.width,cv.height);const d=cx.getImageData(0,0,cv.width,cv.height).data;let sum=0,n=0,dark=0;for(let i=0;i<d.length;i+=32){const l=(.2126*d[i]+.7152*d[i+1]+.0722*d[i+2])/255;sum+=l;n++;if(l<.012)dark++}return{mean:sum/Math.max(1,n),darkRatio:dark/Math.max(1,n)}}
async function loadFirst(north){let last=null;for(const layer of LAYERS){const url=urlFor(north,layer);try{const image=await loadImage(url),signal=imageSignal(image);if(signal.mean<.018||signal.darkRatio>.92)throw new Error(`POLAR_GEOGRAPHIC_IMAGE_SIGNAL:${signal.mean.toFixed(4)}:${signal.darkRatio.toFixed(4)}`);return Object.freeze({image,layer,url,signal})}catch(error){last=error}}throw new Error(`POLAR_GEOGRAPHIC_NO_GIBS_LAYER:${last?.message||'unknown'}`)}
function buildGeometry(C,north){const ringVerts=RINGS*(SEGMENTS+1),centerStart=ringVerts,vertexCount=ringVerts+SEGMENTS,positions=new Float64Array(vertexCount*3),st=new Float32Array(vertexCount*2),span=90-EDGE_LAT;let vi=0;for(let r=0;r<RINGS;r++){const t=r/(RINGS-.5),lat=north?EDGE_LAT+span*t:-EDGE_LAT-span*t,v=north?(lat-EDGE_LAT)/span:(lat+90)/span;for(let s=0;s<=SEGMENTS;s++){const u=s/SEGMENTS,lon=-180+360*u,p=C.Cartesian3.fromDegrees(lon,lat,HEIGHT_M);positions[vi*3]=p.x;positions[vi*3+1]=p.y;positions[vi*3+2]=p.z;st[vi*2]=u;st[vi*2+1]=v;vi++}}for(let s=0;s<SEGMENTS;s++){const u=(s+.5)/SEGMENTS,p=C.Cartesian3.fromDegrees(-180+360*u,north?90:-90,HEIGHT_M);positions[vi*3]=p.x;positions[vi*3+1]=p.y;positions[vi*3+2]=p.z;st[vi*2]=u;st[vi*2+1]=north?1:0;vi++}const indices=[];for(let r=0;r<RINGS-1;r++)for(let s=0;s<SEGMENTS;s++){const a=r*(SEGMENTS+1)+s,b=a+1,c=a+(SEGMENTS+1),d=c+1;if(north){indices.push(a,c,b,b,c,d)}else{indices.push(a,b,c,b,d,c)}}const last=(RINGS-1)*(SEGMENTS+1);for(let s=0;s<SEGMENTS;s++){const a=last+s,b=a+1,c=centerStart+s;if(north)indices.push(a,c,b);else indices.push(a,b,c)}return new C.Geometry({attributes:{position:new C.GeometryAttribute({componentDatatype:C.ComponentDatatype.DOUBLE,componentsPerAttribute:3,values:positions}),st:new C.GeometryAttribute({componentDatatype:C.ComponentDatatype.FLOAT,componentsPerAttribute:2,values:st})},indices:C.IndexDatatype.createTypedArray(vertexCount,indices),primitiveType:C.PrimitiveType.TRIANGLES,boundingSphere:C.BoundingSphere.fromVertices(positions)})}
export class PolarGeographicCapRuntime{
 constructor({viewer,Cesium}={}){if(!viewer||viewer.isDestroyed?.())throw new Error('POLAR_GEOGRAPHIC_VIEWER_REQUIRED');this.viewer=viewer;this.C=Cesium||globalThis.Cesium;this.primitives=[];this.sources=[];this.truth='UNINITIALIZED';this.generation=0}
 async load({force=false}={}){const generation=++this.generation;if(this.primitives.length&&!force)return this.truth;this.dispose({preserveGeneration:true});this.truth='LOADING';const assets=await Promise.all([true,false].map(async north=>({north,asset:await loadFirst(north)})));if(generation!==this.generation)return null;for(const {north,asset} of assets){const C=this.C,material=C.Material.fromType('Image',{image:asset.image,repeat:new C.Cartesian2(1,1)}),appearance=new C.EllipsoidSurfaceAppearance({aboveGround:true,faceForward:true,translucent:false,material}),primitive=this.viewer.scene.primitives.add(new C.Primitive({geometryInstances:new C.GeometryInstance({geometry:buildGeometry(C,north)}),appearance,allowPicking:false,asynchronous:false}));this.primitives.push(primitive);this.sources.push(Object.freeze({hemisphere:north?'NORTH':'SOUTH',epsg:'EPSG:4326',layer:asset.layer,edgeLatitudeDeg:north?EDGE_LAT:-EDGE_LAT,truthClass:'NASA_GIBS_GEOGRAPHIC_IMAGERY_ONLY',imageSignal:asset.signal}))}this.truth='NASA_GIBS_GEOGRAPHIC_POLAR_HOLE_FILL_IMAGERY_ONLY';this.viewer.scene.requestRender();return this.truth}
 setVisible(show){for(const p of this.primitives)p.show=!!show;this.viewer.scene.requestRender()}
 getTruth(){return this.truth}
 getSources(){return Object.freeze([...this.sources])}
 dispose({preserveGeneration=false}={}){if(!preserveGeneration)this.generation++;for(const p of this.primitives)try{this.viewer.scene.primitives.remove(p)}catch(_){}this.primitives=[];this.sources=[];this.truth='UNINITIALIZED'}
}
